package com.example.testing;

import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.junit.jupiter.api.extension.ExtendWith;
import static org.junit.jupiter.api.Assertions.*;

@ExtendWith(TimingExtension.class)
public class DataProcessorTest {

    private ResourceBuffer buffer;

    @BeforeEach
    void setUp() {
        buffer = new ResourceBuffer(1024);
        buffer.initialize();
    }

    @AfterEach
    void tearDown() {
        buffer.release();
    }

    @Test
    void testBufferState() {
        assertAll(
            () -> assertTrue(buffer.isOpen(), "Buffer should be open after init"),
            () -> assertEquals(1024, buffer.capacity(), "Capacity must match allocation")
        );
    }

    @ParameterizedTest
    @CsvSource({"input_a.txt, 150", "input_b.txt, 300"})
    void testDataIngestion(String fileName, int expectedBytes) {
        int processed = buffer.ingest(fileName);
        assertEquals(expectedBytes, processed);
    }
}
